SELECT FROM sys_user u
WHERE u.del_flag = '0'
AND (u.dept_id = #{query.deptId} OR d.ancestors = CAST(#{query.deptId} AS VARCHAR) OR d.ancestors LIKE CONCAT(CAST(#{query.deptId} AS VARCHAR), ',%') OR d.ancestors LIKE CONCAT('%,', CAST(#{query.deptId} AS VARCHAR), ',%') OR d.ancestors LIKE CONCAT('%,', CAST(#{query.deptId} AS VARCHAR)))
AND u.dept_id = #{query.deptId}
AND u.user_name ILIKE CONCAT('%', #{query.userName}, '%')
AND u.nick_name ILIKE CONCAT('%', #{query.nickName}, '%')
AND u.phone_number ILIKE CONCAT('%', #{query.phoneNumber}, '%')
AND u.status = #{query.status}
AND u.create_time >= #{query.createdStartTime}
AND u.create_time <= #{query.createdEndTime}
GROUP BY u.id, d.dept_name ORDER BY u.create_time DESC, u.id DESC

SELECT COUNT(1)
FROM sys_user
WHERE keycloak_user_id = #{keycloakUserId}
  AND del_flag = '0'

    AND id != #{excludeId}
